def calculate_simple_gpa(university, student_id):
    '''
    Calculates simple GPA for the given student at the university.
    For each enrollment from university.get_student_enrollments(student_id),
    gets the course using university.get_course(enrollment.course_code),
    multiplies enrollment.get_grade_points() by course.credits,
    sums all points and credits, and returns total_points / total_credits as GPA (0.0-4.0).
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0

    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is not None:
            grade_points = enrollment.get_grade_points()
            credits = course.credits
            total_points += grade_points * credits
            total_credits += credits

    if total_credits == 0:
        return 0.0
    return total_points / total_credits


